import { isEqual } from 'lodash-es';
import React, { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';
import {
  ActionType,
  Column,
  Hooks,
  MetaBase,
  Row,
  TableInstance,
  TableState,
  actions,
  ensurePluginOrder,
  makePropGetter,
} from 'react-table';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';
import {
  ChevronDownSmallIcon,
  ChevronRightSmallIcon,
} from '@dynatrace/strato-icons';

import { Button } from '../../../buttons/button/Button.js';
import {
  DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
} from '../../DataTable/constants.js';
import { _convertColumn } from '../../types/table-type-mappings.js';
import { insertColumn } from '../../utils/column-utils.js';

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/ban-types*/

/** Actions provided by the plugin to trigger state updates */
export const useExpandableRowActions = {
  /** Action definition for toggling a row's expanded state. */
  toggleRowExpanded: 'strato-toggle-row-expand',
  /** Action for setting `expandedRows`. */
  setExpandedRows: 'strato-set-expanded-rows',
};

// override button styles for DataTable
const StyledButton = /* @__PURE__ */ styled(Button)(() => ({
  width: `${Spacings.Size24}`,
  height: `${Spacings.Size20}`,
  padding: `${Spacings.Size0} ${Spacings.Size2} ${Spacings.Size0} ${Spacings.Size2}`,
  borderRadius: `${Spacings.Size4}`,

  '& > svg': {
    width: '18px',
    height: '14px',
    paddingLeft: '1px',
  },
}));

/** Default expand column definition which can be extended on */
export const TABLE_EXPANDABLE_DEFAULT_COLUMN = {
  id: DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  header: '',
  width: 0,
  cell: ({ row }: { row: any }) => {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    const intl = useIntl();

    return (
      <StyledButton
        aria-label={intl.formatMessage({
          defaultMessage: 'Expand row',
          id: 'aautKWm2xJHnuyvy',
          description: 'Aria label used for data table expandable row trigger.',
        })}
        aria-expanded={row.isRowExpanded === true}
        aria-controls={row.ariaControls}
        {...row.getToggleRowExpandedProps()}
        variant="default"
      >
        <Button.Prefix>
          {row.isRowExpanded ? (
            <ChevronDownSmallIcon />
          ) : (
            <ChevronRightSmallIcon />
          )}
        </Button.Prefix>
      </StyledButton>
    );
  },
  canExpand: () => true,
};

const INTERNAL_TABLE_EXPANDABLE_DEFAULT_COLUMN = _convertColumn(
  TABLE_EXPANDABLE_DEFAULT_COLUMN,
);

/**
 * Additional Columns hook, will add a default expander column to the memoed
 * column definition automatically.
 */
function additionalColumn(columns: Column<any>[], { instance }: MetaBase<any>) {
  if (instance.disableExpandableRows) {
    return columns;
  }

  return insertColumn(columns, INTERNAL_TABLE_EXPANDABLE_DEFAULT_COLUMN, [
    DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  ]) as Column<any>[];
}

/**
 * ColumnDeps additional hook. Defines when the memoed columns should be updated.
 * Adds a dependency to be update when an expandableRowTemplate precense changes.
 */
function columnsDeps(deps: any[], { instance }: MetaBase<any>) {
  return [...deps, instance.disableExpandableRows];
}

/**
 * State reducer for the expandable rows.
 * Listens to expandableRowActions and updates the state accordingly.
 */
function reducer(
  state: TableState,
  action: ActionType,
  _prevState: TableState,
) {
  if (action.type === actions.init) {
    return {
      ...state,
      expandedRows: state.expandedRows ?? {},
    };
  }

  if (action.type === actions.resetPage) {
    // The action type `resetPage` is from the usePagination react-table plugin hook and is dispatched regardless
    // if Datatable.Pagination is present or not, when the data for the table changes.
    const expandedRows = {};
    state.onRowsExpandedChange({});

    return {
      ...state,
      expandedRows,
    };
  }

  if (action.type === useExpandableRowActions.toggleRowExpanded) {
    const { rowId, isExpanded } = action;

    // Previous state
    const currentRowExpandedState = state.expandedRows?.[rowId];
    const newRowExpandedState =
      typeof isExpanded !== 'undefined' ? isExpanded : !currentRowExpandedState;

    if (!currentRowExpandedState && newRowExpandedState) {
      const expandedRows = {
        ...state.expandedRows,
        [rowId]: true,
      };

      requestAnimationFrame(() => {
        state.onRowsExpandedChange({ ...expandedRows });
      });

      return {
        ...state,
        expandedRows,
      };
    } else if (currentRowExpandedState && !newRowExpandedState) {
      const { ...newExpandedRowsState } = state.expandedRows;
      delete newExpandedRowsState[rowId];

      requestAnimationFrame(() => {
        state.onRowsExpandedChange?.({ ...newExpandedRowsState });
      });
      return {
        ...state,
        expandedRows: newExpandedRowsState,
      };
    } else {
      return state;
    }
  }

  if (action.type === useExpandableRowActions.setExpandedRows) {
    const { payload: expandedRows } = action as ActionType & {
      payload: Record<string, boolean>;
    };

    const { expandedRows: prevExpandedRows } = _prevState as TableState & {
      expandedRows: Record<string, boolean>;
    };

    const prevExpandedRowsFiltered = Object.fromEntries(
      Object.entries(prevExpandedRows).filter(
        ([_, shouldExpand]) => shouldExpand,
      ),
    );

    const newExpandedRows = Object.fromEntries(
      Object.entries(expandedRows).filter(([_, shouldExpand]) => shouldExpand),
    );

    if (!isEqual(prevExpandedRowsFiltered, newExpandedRows)) {
      requestAnimationFrame(() => {
        state.onRowsExpandedChange({ ...newExpandedRows });
      });
    }

    return {
      ...state,
      expandedRows: newExpandedRows,
    };
  }
}

/**
 * UseInstance hook for the expandable row.
 * Defining the necessary data and hooks and providing them via the instance.
 */
function useInstance(instance: TableInstance<any>) {
  const {
    dispatch,
    rows,
    state,
    columns,
    id: uniqueTableId,
    plugins,
  } = instance;

  ensurePluginOrder(plugins, ['useSubRows'], 'useExpandableRow');

  const toggleExpandableRow = useCallback(
    (rowId: number, isExpanded: boolean) => {
      dispatch({
        type: useExpandableRowActions.toggleRowExpanded,
        rowId,
        isExpanded,
      });
    },
    [dispatch],
  );

  const rowCanExpandFn = useCallback(
    (row: Row) => {
      const col = columns.find(
        (column) => column.id === TABLE_EXPANDABLE_DEFAULT_COLUMN.id,
      );
      if (col && col.canExpand) {
        return col.canExpand(row);
      } else {
        return TABLE_EXPANDABLE_DEFAULT_COLUMN.canExpand();
      }
    },
    [columns],
  );

  const expandedRows = useMemo(() => {
    const expandedRows: Row[] = [];

    for (const row of rows) {
      row.isRowExpanded =
        state.expandedRows !== undefined && state.expandedRows[row.id];

      row.canExpandRow = rowCanExpandFn(row);
      row.ariaControls = `${uniqueTableId}-${row.index}`;
      expandedRows.push(row);
    }
    return expandedRows;
  }, [state.expandedRows, rowCanExpandFn, uniqueTableId, rows]);

  Object.assign(instance, {
    toggleExpandableRow,
    rows: expandedRows,
  });
}

/**
 * PrepareRow hook which will bind the getToggleRowExpandedProps to each row,
 * making it available for the trigger cell renderer
 */
function prepareRow(row: Row<any>, { instance }: MetaBase<any>) {
  if (instance.disableExpandableRows) {
    return;
  }

  row.toggleRowExpanded = (set) => instance.toggleExpandableRow(row.id, set);
  row.getToggleRowExpandedProps = makePropGetter(
    instance.getHooks().getToggleRowExpandedProps,
    { instance, row },
  );
}

/** Default prop getter for the expandable toggle. This will add necessary handles to the trigger button. */
function defaultGetToggleRowExpandedProps(
  props: any[],
  { row }: { row: Row<any> },
) {
  return [
    props,
    {
      onClick: () => {
        row.toggleRowExpanded();
      },
      disabled: !row.canExpandRow,
    },
  ];
}

/** Table hook that enables expandable rows on tables */
export function useExpandableRow<D extends Record<string, unknown>>(
  hooks: Hooks<D>,
): void {
  hooks.columns.push(additionalColumn);
  hooks.columnsDeps.push(columnsDeps);
  hooks.getToggleRowExpandedProps = [defaultGetToggleRowExpandedProps];
  hooks.stateReducers.push(reducer);
  hooks.useInstance.push(useInstance);
  hooks.prepareRow.push(prepareRow);
}

useExpandableRow.pluginName = 'useExpandableRow';
